export function invoiceLine(value: string): string {
	return value.trim();
}

import { expect, test } from 'vitest';
import { invoiceLine } from '../../src/utils/invoiceLine';

test('invoiceLine trims values', () => {
	expect(invoiceLine(' value ')).toBe('value');
});

